//! The job helper's runner-host rows: they run inside a fake runner (`test/runners/`), as the user `runner` with its
//! user manager and rootless podman, with the real `sleipnir` and `drgnx-key` beside them (`SLEIPNIR_TEST_BIN`), never
//! on a developer's machine:
//!
//! ```text
//! cargo test -p sleipnir --features test-hooks --test runner_host_helper --no-run
//! fleet.sh host <the test binary> [FILTER]      # --ignored, in every runner
//! ```
//!
//! Every key is generated by the test; no value is ever printed, the assertions only say where one was found.
//! Each row names its pattern.
#![cfg(target_os = "linux")]

use sleipnir::helper::keys;
use sleipnir::linux::jobexec::{HelperSpec, JobExec};
use sleipnir::linux::parse::Parser;
use sleipnir::linux::podman::{
    self, Caps, ContainerImage, ContainerReq, KeyMounts, RunnerArgs, RunnerMounts,
};
use sleipnir::linux::result::ResultJson;
use sleipnir::linux::{slices, unit};
use std::fs;
use std::io::{BufRead, BufReader, Read};
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

/// The fake runner's base image, preloaded in its store.
const BASE: &str = "registry.fedoraproject.org/fedora:45";
/// The slice root and the container prefix of these rows: never a real runner's.
const ROOT: &str = "slhelp";
const PREFIX: &str = "slhelp-run-";

fn sleipnir_bin() -> PathBuf {
    std::env::var_os("SLEIPNIR_TEST_BIN")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_BIN_EXE_sleipnir")))
}

/// drgnx-key beside the sleipnir under test (`fleet.sh host` copies both).
fn drgnx_key_bin() -> PathBuf {
    match std::env::var_os("SLEIPNIR_TEST_BIN") {
        Some(s) => PathBuf::from(s).with_file_name("drgnx-key"),
        None => PathBuf::from(env!("CARGO_BIN_EXE_drgnx-key")),
    }
}

/// A fresh value no test output ever shows: 32 hex digits from the kernel's random source.
fn secret() -> String {
    let mut b = [0u8; 16];
    fs::File::open("/dev/urandom")
        .unwrap()
        .read_exact(&mut b)
        .unwrap();
    b.iter().map(|x| format!("{x:02x}")).collect()
}

fn holds(hay: &[u8], needle: &[u8]) -> bool {
    hay.windows(needle.len()).any(|w| w == needle)
}

/// Every regular file under DIR (never following a link, none over 64 MiB) that holds NEEDLE.
fn files_holding(dir: &Path, needle: &[u8], found: &mut Vec<PathBuf>) {
    let Ok(rd) = fs::read_dir(dir) else { return };
    for e in rd.flatten() {
        let Ok(ft) = e.file_type() else { continue };
        if ft.is_dir() {
            files_holding(&e.path(), needle, found);
        } else if ft.is_file()
            && e.metadata().is_ok_and(|m| m.len() <= 64 << 20)
            && fs::read(e.path()).is_ok_and(|b| holds(&b, needle))
        {
            found.push(e.path());
        }
    }
}

/// A runner folder in the runner's /tmp with one attempt's folder, `jobs/<id>.1`.
struct Attempt {
    _t: tempfile::TempDir,
    root: PathBuf,
    dir: PathBuf,
}

fn attempt_in(root: &Path, id: &str) -> PathBuf {
    let dir = root.join("jobs").join(format!("{id}.1"));
    fs::create_dir_all(dir.join("target")).unwrap();
    dir
}

fn attempt(id: &str) -> Attempt {
    let t = tempfile::Builder::new()
        .prefix("slhelp")
        .tempdir_in("/tmp")
        .unwrap();
    let root = t.path().to_path_buf();
    let dir = attempt_in(&root, id);
    Attempt { _t: t, root, dir }
}

fn spec(id: &str, dir: &Path, argv: Vec<String>, helper: HelperSpec) -> JobExec {
    JobExec {
        id: id.into(),
        attempt: 1,
        machine: "runner".into(),
        slice: slices::job_slice(ROOT, id).unwrap(),
        argv,
        env: vec![],
        cwd: None,
        log: dir.join("log"),
        state_logs: vec![],
        keyed: !helper.keys.is_empty(),
        parser: Parser::Exit,
        expect: forseti::Expect::default(),
        grant: forseti::Grant {
            cores: 1,
            mem_cap_mib: 256,
            reserve_mib: 128,
        },
        timeout_s: 300,
        helper: Some(helper),
    }
}

/// The helper of DIR's job, started by the test as job-exec starts it; its stdin ends it.
struct Helper {
    child: Child,
    pid: u32,
}

impl Helper {
    fn start(dir: &Path, extra: &[&str]) -> Helper {
        let mut child = Command::new(sleipnir_bin())
            .arg("job-helper")
            .arg("--dir")
            .arg(dir)
            .args(extra)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .spawn()
            .unwrap();
        let mut line = String::new();
        BufReader::new(child.stdout.take().unwrap())
            .read_line(&mut line)
            .unwrap();
        let pid = line
            .strip_prefix("ready ")
            .and_then(|p| p.trim().parse().ok())
            .unwrap_or_else(|| panic!("the helper's first line: {line:?}"));
        Helper { child, pid }
    }
}

impl Drop for Helper {
    fn drop(&mut self) {
        drop(self.child.stdin.take());
        let _ = self.child.wait();
    }
}

fn uid() -> u32 {
    fs::metadata("/proc/self").unwrap().uid()
}

/// [C] The helper, announced by its `ready` line, is not dumpable: its /proc files belong to root and its
/// environment can't be read by its own user, unlike a plain child of the same user beside it.
#[test]
#[ignore = "runner-host"]
fn helper_is_not_dumpable() {
    let a = attempt("dump1");
    spec("dump1", &a.dir, vec!["true".into()], HelperSpec::default())
        .write(&a.dir)
        .unwrap();
    let h = Helper::start(&a.dir, &[]);
    let mut plain = Command::new("sleep").arg("600").spawn().unwrap();
    let me = uid();
    assert_ne!(me, 0, "the row runs as the runner user");
    let owner = |pid: u32| fs::metadata(format!("/proc/{pid}/environ")).unwrap().uid();
    assert_eq!(owner(plain.id()), me, "a dumpable child is its user's");
    assert!(fs::read(format!("/proc/{}/environ", plain.id())).is_ok());
    assert_ne!(
        owner(h.pid),
        me,
        "the helper's /proc files are not its user's"
    );
    assert!(
        fs::read(format!("/proc/{}/environ", h.pid)).is_err(),
        "the helper's environment was readable"
    );
    let _ = plain.kill();
    let _ = plain.wait();
}

/// [C] A key request waits for its key, then `drgnx-key` exits 75 having printed nothing, and the helper has recorded
/// the request first; once the key is handed over, the same request gets it, and the read is recorded by name only.
/// A key the job doesn't name is refused at once.
#[test]
#[ignore = "runner-host"]
fn drgnx_key_blocks_then_75_and_the_helper_records_it() {
    let a = attempt("block1");
    let h = HelperSpec {
        keys: vec!["TOKEN".into()],
        ..HelperSpec::default()
    };
    spec("block1", &a.dir, vec!["true".into()], h)
        .write(&a.dir)
        .unwrap();
    let _h = Helper::start(&a.dir, &["--key-wait-s", "2"]);
    let get = |name: &str| {
        Command::new(drgnx_key_bin())
            .args(["get", name])
            .env("DRGNX_KEY_SOCK", a.dir.join(keys::KEY_SOCK))
            .output()
            .unwrap()
    };
    let t0 = Instant::now();
    let out = get("TOKEN");
    assert_eq!(
        out.status.code(),
        Some(75),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        t0.elapsed() >= Duration::from_secs(2),
        "it didn't wait for the key"
    );
    assert!(out.stdout.is_empty());
    assert_eq!(keys::timed_out(&a.dir), ["TOKEN"], "the helper's record");

    let value = secret();
    keys::hand(&a.dir.join(keys::HELPER_SOCK), "TOKEN", value.as_bytes()).unwrap();
    let out = get("TOKEN");
    assert_eq!(
        out.status.code(),
        Some(0),
        "{}",
        String::from_utf8_lossy(&out.stderr)
    );
    assert!(
        out.stdout == value.as_bytes(),
        "drgnx-key get printed another value"
    );
    let uses = fs::read_to_string(a.dir.join(keys::KEY_USE)).unwrap();
    assert!(
        uses.contains("\"TOKEN\"") && !uses.contains(&value),
        "the key-use record"
    );

    let out = get("OTHER");
    assert_eq!(out.status.code(), Some(64));
    assert!(String::from_utf8_lossy(&out.stderr).contains("doesn't name the key"));
    assert_eq!(
        keys::timed_out(&a.dir),
        ["TOKEN"],
        "a refusal is no timeout"
    );
    // the helper takes only the names the job lists
    assert!(keys::hand(&a.dir.join(keys::HELPER_SOCK), "OTHER", b"x").is_err());
}

fn base_ref() -> String {
    let out = Command::new("podman")
        .args(["image", "inspect", BASE, "--format", "{{.Digest}}"])
        .output()
        .unwrap();
    assert!(out.status.success());
    format!(
        "registry.fedoraproject.org/fedora@{}",
        String::from_utf8_lossy(&out.stdout).trim()
    )
}

fn podman_out(args: &[&str]) -> Vec<u8> {
    Command::new("podman").args(args).output().unwrap().stdout
}

/// [C] A keyed container runs its command as `drgnx-key exec`: the command's own environment (its `/proc/<pid>/environ`,
/// read from the runner) holds the variable with the key's value, while podman's argv, `podman inspect` and the
/// container's stored config and runtime state hold the names only. The command announces itself by a file.
#[test]
#[ignore = "runner-host"]
fn drgnx_key_exec_sets_env_in_the_process_only() {
    let a = attempt("env1");
    let h = HelperSpec {
        keys: vec!["TOKEN".into()],
        ..HelperSpec::default()
    };
    spec("env1", &a.dir, vec!["true".into()], h)
        .write(&a.dir)
        .unwrap();
    let _h = Helper::start(&a.dir, &[]);
    let value = secret();
    keys::hand(&a.dir.join(keys::HELPER_SOCK), "TOKEN", value.as_bytes()).unwrap();
    let key_copy = a.dir.join("drgnx-key");
    fs::copy(drgnx_key_bin(), &key_copy).unwrap();
    let src = a.dir.join("src");
    fs::create_dir_all(&src).unwrap();
    let req = ContainerReq {
        image: "base".into(),
        argv: ["sh", "-c", "touch /target/started; exec sleep 600"]
            .map(String::from)
            .to_vec(),
        worktree: src,
        subdir: PathBuf::new(),
        job: "env1".into(),
        net: false,
        runner: Some(RunnerMounts {
            writes_tree: false,
            target: a.dir.join("target"),
            caches: vec![],
            keys: Some(KeyMounts {
                socket: a.dir.join(keys::KEY_SOCK),
                helper: key_copy,
                vars: vec![("TOKEN".into(), "JOB_TOKEN".into())],
            }),
        }),
    };
    let caps = Caps {
        images: vec![ContainerImage {
            name: "base".into(),
            image: base_ref(),
        }],
        memory: "256M".into(),
        cpus: 1,
        pids: 100,
        proxy: None,
        net_hosts: vec![],
    };
    let ra = RunnerArgs {
        cgroup_parent: None,
        label: None,
        name_prefix: PREFIX.into(),
    };
    let argv: Vec<String> = podman::argv(&req, &caps, &ra)
        .unwrap()
        .into_iter()
        .map(|s| s.into_string().unwrap())
        .collect();
    assert!(
        !argv.iter().any(|s| s.contains(&value)),
        "the key is in podman's argv"
    );
    let name = format!("{PREFIX}env1");
    let mut run = Command::new("podman")
        .args(&argv)
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    skuld::wait_until("the command started", 120, || {
        a.dir.join("target/started").exists().then_some(())
    });
    let pid: u32 =
        String::from_utf8_lossy(&podman_out(&["inspect", "-f", "{{.State.Pid}}", &name]))
            .trim()
            .parse()
            .unwrap();
    let environ = fs::read(format!("/proc/{pid}/environ")).unwrap();
    let want = format!("JOB_TOKEN={value}");
    assert!(
        environ.split(|b| *b == 0).any(|v| v == want.as_bytes()),
        "the command's environment lacks the key's variable"
    );
    let inspect = podman_out(&["inspect", &name]);
    assert!(
        holds(&inspect, b"TOKEN=JOB_TOKEN"),
        "podman inspect shows the names"
    );
    assert!(
        !holds(&inspect, value.as_bytes()),
        "the key is in podman inspect"
    );
    let id = String::from_utf8_lossy(&podman_out(&["inspect", "-f", "{{.Id}}", &name]))
        .trim()
        .to_string();
    let home = PathBuf::from(std::env::var_os("HOME").unwrap());
    let storage = home.join(".local/share/containers/storage");
    let runtime = PathBuf::from(std::env::var_os("XDG_RUNTIME_DIR").unwrap());
    let mut found = vec![];
    for d in [
        storage.join("overlay-containers").join(&id),
        storage.join("libpod"),
        storage.join("db.sql"),
        runtime.join("containers"),
        runtime.join("libpod"),
        a.root.clone(),
    ] {
        if d.is_file() {
            if fs::read(&d).is_ok_and(|b| holds(&b, value.as_bytes())) {
                found.push(d);
            }
        } else {
            files_holding(&d, value.as_bytes(), &mut found);
        }
    }
    let _ = Command::new("podman")
        .args(["rm", "-f", "-t", "0", &name])
        .output();
    let _ = run.wait();
    assert!(found.is_empty(), "the key's value is in {found:?}");
}

fn unit_req(name: &str, s: &JobExec, dir: &Path) -> unit::UnitReq {
    unit::UnitReq {
        unit: name.into(),
        id: s.id.clone(),
        attempt: 1,
        slice: s.slice.clone(),
        runtime_max_s: 600,
        log: s.log.clone(),
        env: vec![],
        argv: vec![
            sleipnir_bin().display().to_string(),
            "job-exec".into(),
            dir.display().to_string(),
        ],
        binds_to: None,
    }
}

fn helper_pid(dir: &Path) -> u32 {
    skuld::wait_until("the helper's pid", 120, || {
        fs::read_to_string(dir.join(sleipnir::helper::PID))
            .ok()?
            .trim()
            .parse()
            .ok()
    })
}

fn cgroup_of(pid: u32) -> String {
    fs::read_to_string(format!("/proc/{pid}/cgroup"))
        .unwrap_or_default()
        .lines()
        .find_map(|l| l.strip_prefix("0::"))
        .unwrap_or("")
        .to_string()
}

/// [C] job-exec starts the helper inside the job's own unit (it announces its pid once it listens); stopping the
/// unit ends the helper with it, and its key socket can't be reached any more.
#[test]
#[ignore = "runner-host"]
fn the_helper_dies_with_the_job_unit() {
    let a = attempt("bind1");
    let h = HelperSpec {
        keys: vec!["TOKEN".into()],
        ..HelperSpec::default()
    };
    let s = spec("bind1", &a.dir, vec!["sleep".into(), "600".into()], h);
    s.write(&a.dir).unwrap();
    let u = unit::start(&unit_req("slhelp-bind1-1", &s, &a.dir)).unwrap();
    let pid = helper_pid(&a.dir);
    let main: u32 = String::from_utf8_lossy(
        &Command::new("systemctl")
            .args(["--user", "show", "-p", "MainPID", "--value", &u])
            .output()
            .unwrap()
            .stdout,
    )
    .trim()
    .parse()
    .unwrap();
    assert_eq!(
        cgroup_of(pid),
        cgroup_of(main),
        "the helper runs in the job's unit"
    );
    assert!(cgroup_of(pid).contains(&s.slice), "and in the job's slice");
    unit::stop(&u).unwrap();
    skuld::wait_until("the helper gone", 120, || {
        (!Path::new(&format!("/proc/{pid}")).exists()).then_some(())
    });
    assert!(
        std::os::unix::net::UnixStream::connect(a.dir.join(keys::KEY_SOCK)).is_err(),
        "the key socket still answers"
    );
}

/// [C] Two jobs with their helpers in their units: one has grown 8 MB since its start, the other 1 MB, and each
/// announces it by a file. Then the runner folder reads below its floor (the test build's facts file: a fake runner
/// shares the host's disk). The job that grew most is stopped `infra: disk`, before the other job's helper stops
/// anything.
#[test]
#[ignore = "runner-host"]
fn a_job_that_grew_most_is_stopped_below_the_floor() {
    let a = attempt("gbig");
    let small_dir = attempt_in(&a.root, "gsml");
    let job = |id: &str, dir: &Path, bytes: u64| {
        let cmd = format!(
            "head -c {bytes} /dev/zero > '{d}/target/fill' && touch '{d}/filled' && exec sleep 600",
            d = dir.display()
        );
        let h = HelperSpec {
            root: a.root.clone(),
            ..HelperSpec::default()
        };
        let s = spec(id, dir, vec!["sh".into(), "-c".into(), cmd], h);
        s.write(dir).unwrap();
        unit::start(&unit_req(&format!("slhelp-{id}-1"), &s, dir)).unwrap()
    };
    let big = job("gbig", &a.dir, 8_000_000);
    let small = job("gsml", &small_dir, 1_000_000);
    for d in [&a.dir, &small_dir] {
        skuld::wait_until("the job filled its folder", 120, || {
            d.join("filled").exists().then_some(())
        });
    }
    fs::write(
        a.root.join("test-machine.json"),
        r#"{"disk_free_gb": 1, "disk_total_gb": 100}"#,
    )
    .unwrap();
    let r = skuld::wait_until("the big job's result", 120, || {
        ResultJson::read(&a.dir).ok()
    });
    let _ = fs::remove_file(a.root.join("test-machine.json"));
    assert_eq!(
        (r.verdict, r.infra.as_deref()),
        (forseti::Verdict::Infra("disk".into()), Some("infra: disk"))
    );
    let result_at = fs::metadata(a.dir.join("result.json"))
        .unwrap()
        .modified()
        .unwrap();
    if let Ok(m) = fs::metadata(small_dir.join("kill_reason")) {
        assert!(
            m.modified().unwrap() >= result_at,
            "the small job was stopped before the one that grew most"
        );
    }
    let _ = unit::stop(&big);
    let _ = unit::stop(&small);
}
